"""Tests for _pick_join_event: which meeting `pa join` opens."""

from datetime import datetime, timedelta, timezone

from personal_assistant_dashboard.dashboard import _pick_join_event

NOW = datetime(2026, 10, 6, 10, 0, tzinfo=timezone.utc)
LEAD = timedelta(minutes=5)


def _event(
    summary: str,
    start_min: int,
    end_min: int,
    *,
    response: str = "accepted",
    solo: bool = False,
) -> dict:
    attendees = [{"email": "me@example.com", "self": True, "response_status": response}]
    if not solo:
        attendees.append({"email": "other@example.com"})
    return {
        "summary": summary,
        "start": (NOW + timedelta(minutes=start_min)).isoformat(),
        "end": (NOW + timedelta(minutes=end_min)).isoformat(),
        "attendees": attendees,
    }


def _pick(*events: dict) -> str | None:
    picked = _pick_join_event(list(events), NOW, LEAD)
    return picked["summary"] if picked else None


def test_latest_started_active_wins() -> None:
    assert _pick(_event("early", -30, 30), _event("late", -5, 25)) == "late"


def test_active_beats_upcoming() -> None:
    assert _pick(_event("soon", 2, 30), _event("now", -10, 20)) == "now"


def test_upcoming_within_lead() -> None:
    assert _pick(_event("later", 4, 30), _event("sooner", 3, 30)) == "sooner"
    assert _pick(_event("too far", 6, 30)) is None


def test_ended_meeting_not_picked() -> None:
    assert _pick(_event("over", -30, 0)) is None


def test_solo_and_declined_skipped() -> None:
    assert _pick(_event("focus", -5, 30, solo=True)) is None
    assert _pick(_event("nope", -5, 30, response="declined")) is None
